/**
 * P4: the Barrowman fin-body interference diameter must be the body the fin is
 * mounted on, not the last body component in array order.
 *
 * Anchors:
 * - `crates/astraea-engine/tests/fixtures/p4-stability-baseline-ts.json`
 *   (generated by `p4Baseline.test.ts` before the production edit): unaffected
 *   designs must reproduce it exactly.
 * - `crates/astraea-engine/tests/fixtures/p4-fin-station.json` (post-fix Rust
 *   fixture): the TS mirror must agree to 1e-12 relative.
 * - closed-form interference ratios and the Gate 1 predictions for the five
 *   affected Round 2 input vehicles (their frozen predictions are untouched).
 */
import { describe, expect, it } from 'vitest';
import tsBaselineJson from '../../crates/astraea-engine/tests/fixtures/p4-stability-baseline-ts.json';
import rustParityJson from '../../crates/astraea-engine/tests/fixtures/p4-fin-station.json';
import { PRESET_ESTES_ALPHA, PRESET_NASA_STUDENT_LAUNCH, PRESET_SPACEPORT_AMERICA } from '../state/presets';
import { ARCAS_SHORT, ARCAS_LONG } from '../validation/arcas/arcas-vehicle';
import { NOMINAL, ROUND2_VEHICLES, buildVehicle } from '../validation/round2/vehicles';
import {
  computeEllipticalFinAero,
  computeFreeformFinAero,
  computeRocketStability,
  computeTrapezoidFinAero,
} from './barrowman';
import { trapezoidPlanformPoints } from './finPlanform';
import { computeAerodynamicCurves } from './transonicAero';
import type {
  EllipticalFinSetComponent,
  FreeformFinSetComponent,
  RocketComponent,
  RocketVehicle,
  TrapezoidFinSetComponent,
} from '../core/types';

interface TsBaseline {
  designs: Record<string, {
    role: string;
    stability: {
      totalCna: number;
      cp: number;
      staticMarginCalibers: number;
      cg: number;
      contributions: Array<{ id: string; cna: number; cp: number }>;
    };
  }>;
}

const tsBaseline = tsBaselineJson as unknown as TsBaseline;
const rustParity = rustParityJson as unknown as {
  designs: Record<string, { totalCna: number; cp: number; contributions: Array<{ id: string; cna: number; cp: number }> }>;
};

function rel(got: number, want: number): number {
  return Math.abs(got - want) / Math.max(1, Math.abs(want));
}

function vehicle(components: RocketComponent[]): RocketVehicle {
  return { id: 'p4', name: 'p4', version: '1', author: 'test', components };
}

const nose = (length: number, baseDiameter: number): RocketComponent => ({
  id: 'nose', name: 'nose', type: 'nosecone', materialId: 'cardboard',
  shape: 'conical', length, baseDiameter, wallThickness: 0.002, isHollow: true,
});
const tube = (id: string, length: number, outerDiameter: number): RocketComponent => ({
  id, name: id, type: 'bodytube', materialId: 'cardboard',
  length, outerDiameter, innerDiameter: outerDiameter - 0.002,
});
const transition = (id: string, length: number, foreDiameter: number, aftDiameter: number): RocketComponent => ({
  id, name: id, type: 'transition', materialId: 'cardboard',
  length, foreDiameter, aftDiameter, wallThickness: 0.002, isHollow: true,
});
const fins = (overrides: Partial<TrapezoidFinSetComponent> = {}): TrapezoidFinSetComponent => ({
  id: 'fins', name: 'fins', type: 'trapezoidfinset', materialId: 'balsa',
  finCount: 4, rootChord: 0.1, tipChord: 0.05, span: 0.06, sweepLength: 0.03,
  thickness: 0.003, crossSection: 'rounded', axialOffset: 0.3, ...overrides,
});

function finContribution(v: RocketVehicle, id = 'fins') {
  const s = computeRocketStability(v);
  const c = s.contributions.find((x) => x.id === id)!;
  return { s, c };
}

describe('P4 fin interference station', () => {
  it('unaffected designs reproduce the frozen TS baseline exactly', () => {
    for (const [id, v] of [
      ['alpha', PRESET_ESTES_ALPHA],
      ['nasa-sl', PRESET_NASA_STUDENT_LAUNCH],
    ] as const) {
      const s = computeRocketStability(v);
      const b = tsBaseline.designs[id].stability;
      expect(s.totalCNa, `${id} totalCNa`).toBe(b.totalCna);
      expect(s.cp, `${id} cp`).toBe(b.cp);
      expect(s.staticMarginCalibers, `${id} margin`).toBe(b.staticMarginCalibers);
      for (const want of b.contributions) {
        const got = s.contributions.find((c) => c.id === want.id)!;
        expect(got.cna, `${id} ${want.id} cna`).toBe(want.cna);
        expect(got.cp, `${id} ${want.id} cp`).toBe(want.cp);
      }
    }
  });

  it('the TS mirror matches the post-fix Rust fixture to 1e-12 relative', () => {
    const designs = [
      ['alpha', PRESET_ESTES_ALPHA],
      ['nasa-sl', PRESET_NASA_STUDENT_LAUNCH],
      ['spaceport', PRESET_SPACEPORT_AMERICA],
      ['arcas-short', ARCAS_SHORT],
      ['arcas-long', ARCAS_LONG],
      ['taper-mount', vehicle([
        { id: 'n', name: 'n', type: 'nosecone', materialId: 'cardboard', shape: 'conical',
          length: 0.1, baseDiameter: 0.06, wallThickness: 0.002, isHollow: true },
        tube('b', 0.4, 0.06),
        transition('t', 0.2, 0.06, 0.04),
        { id: 'f', name: 'f', type: 'trapezoidfinset', materialId: 'balsa', finCount: 4,
          rootChord: 0.01, tipChord: 0.05, span: 0.06, sweepLength: 0.03,
          thickness: 0.003, crossSection: 'rounded', axialOffset: 0.45 },
      ])],
      ['nose-mount', vehicle([
        { id: 'n', name: 'n', type: 'nosecone', materialId: 'cardboard', shape: 'vonkarman',
          length: 0.4, baseDiameter: 0.08, wallThickness: 0.002, isHollow: true },
        { id: 'f', name: 'f', type: 'trapezoidfinset', materialId: 'balsa', finCount: 4,
          rootChord: 0.2, tipChord: 0.05, span: 0.06, sweepLength: 0.03,
          thickness: 0.003, crossSection: 'rounded', axialOffset: 0.1 },
      ])],
    ] as const;
    for (const [id, source] of designs) {
      const s = computeRocketStability(source);
      const want = rustParity.designs[id];
      expect(rel(s.totalCNa, want.totalCna), `${id} totalCna`).toBeLessThanOrEqual(1e-12);
      expect(rel(s.cp, want.cp), `${id} cp`).toBeLessThanOrEqual(1e-12);
      for (const w of want.contributions) {
        const got = s.contributions.find((c) => c.id === w.id)!;
        expect(rel(got.cna!, w.cna), `${id} ${w.id} cna`).toBeLessThanOrEqual(1e-12);
        expect(rel(got.cp!, w.cp), `${id} ${w.id} cp`).toBeLessThanOrEqual(1e-12);
      }
    }
  });

  it('a boattail after the fin set does not supply the interference radius', () => {
    const v = vehicle([nose(0.2, 0.06), tube('bt', 0.4, 0.06), transition('tr', 0.1, 0.06, 0.04), fins()]);
    const { c } = finContribution(v);
    const expected = computeTrapezoidFinAero(fins(), 0.5, 0.06, 0.06);
    expect(c.cna).toBe(expected.cna);
    expect(c.cp).toBe(expected.cp);
    expect(computeTrapezoidFinAero(fins(), 0.5, 0.04, 0.06).cna).not.toBe(c.cna);
  });

  it('a straddling root uses the greatest chord overlap and exact ties go forward', () => {
    // Binary-exact geometry: tube 0.25..1.0, transition 1.0..1.5.
    const base = [nose(0.25, 0.06), tube('bt', 0.75, 0.06), transition('tr', 0.5, 0.06, 0.04)];
    const tubeMajor = fins({ axialOffset: 0.45, rootChord: 0.2 }); // 0.7..0.9
    expect(finContribution(vehicle([...base, tubeMajor])).c.cna)
      .toBe(computeTrapezoidFinAero(tubeMajor, 0.7, 0.06, 0.06).cna);

    const tie = fins({ axialOffset: 0.5, rootChord: 0.5 }); // 0.75..1.25
    expect(finContribution(vehicle([...base, tie])).c.cna)
      .toBe(computeTrapezoidFinAero(tie, 0.75, 0.06, 0.06).cna);

    const boattailMajor = fins({ axialOffset: 0.65, rootChord: 0.5 }); // 0.9..1.4, mid 1.15
    const localTaper = 0.06 + (0.04 - 0.06) * ((1.15 - 1.0) / 0.5);
    expect(finContribution(vehicle([...base, boattailMajor])).c.cna)
      .toBe(computeTrapezoidFinAero(boattailMajor, 0.9, localTaper, 0.06).cna);
  });

  it('a root ending at a joint keeps the upstream body (no spurious move)', () => {
    const fin = fins({ axialOffset: 0.35, rootChord: 0.05 }); // 0.55..0.60, tube ends at 0.6
    const v = vehicle([nose(0.2, 0.06), tube('bt', 0.4, 0.06), transition('tr', 0.1, 0.06, 0.04), fin]);
    expect(finContribution(v).c.cna).toBe(computeTrapezoidFinAero(fin, 0.55, 0.06, 0.06).cna);
  });

  it('a root on a transition uses the local diameter at its mid chord', () => {
    const fin = fins({ axialOffset: 0.45, rootChord: 0.05 }); // 0.65..0.70, mid 0.675
    const v = vehicle([nose(0.2, 0.06), tube('bt', 0.4, 0.06), transition('tr', 0.1, 0.06, 0.04), fin]);
    const local = 0.06 + (0.04 - 0.06) * ((0.675 - 0.6) / 0.1);
    expect(finContribution(v).c.cna).toBe(computeTrapezoidFinAero(fin, 0.65, local, 0.06).cna);
    // It must not keep the old far-end (aft) diameter.
    expect(finContribution(v).c.cna).not.toBe(computeTrapezoidFinAero(fin, 0.65, 0.04, 0.06).cna);
  });

  it("the reviewer's taper probe uses the root-local diameter", () => {
    // tail 0.5..0.7, D 0.06->0.04, root 0.55..0.56; local D at 0.555 is 0.0545.
    const fin = fins({ axialOffset: 0.45, rootChord: 0.01 });
    const v = vehicle([nose(0.1, 0.06), tube('b', 0.4, 0.06), transition('t', 0.2, 0.06, 0.04), fin]);
    const cna = finContribution(v).c.cna!;
    const local = 0.06 + (0.04 - 0.06) * ((0.555 - 0.5) / 0.2);
    expect(cna).toBe(computeTrapezoidFinAero(fin, 0.55, local, 0.06).cna);
    // Reviewer's bounds: strictly above the aft-local lower bound (D=0.054)
    // and below the fore-local value (D=0.055); the old code gave D=0.04.
    expect(cna).toBeGreaterThan(computeTrapezoidFinAero(fin, 0.55, 0.054, 0.06).cna);
    expect(cna).toBeLessThan(computeTrapezoidFinAero(fin, 0.55, 0.055, 0.06).cna);
    expect(cna).not.toBe(computeTrapezoidFinAero(fin, 0.55, 0.04, 0.06).cna);
  });

  it("the reviewer's decimal 50/50 joint goes forward", () => {
    // nose .1 + tube .4 => joint 0.5; root 0.4..0.6. Raw overlaps differ in the
    // last bits; within 1e-9*chord they are a tie -> forward tube.
    const fin = fins({ axialOffset: 0.3, rootChord: 0.2 });
    const v = vehicle([nose(0.1, 0.06), tube('b', 0.4, 0.06), transition('t', 0.2, 0.06, 0.04), fin]);
    const cna = finContribution(v).c.cna!;
    expect(cna).toBe(computeTrapezoidFinAero(fin, 0.4, 0.06, 0.06).cna);
    expect(cna).not.toBe(computeTrapezoidFinAero(fin, 0.4, 0.04, 0.06).cna);
  });

  it('a nose-mounted root uses the published profile radius at mid chord', () => {
    // Conical nose 0..0.4, base 0.08; root 0.1..0.3, mid 0.2 -> u=0.5 -> D=0.04.
    const coneFin = fins({ axialOffset: 0.1, rootChord: 0.2 });
    const cone = vehicle([
      { id: 'nose', name: 'nose', type: 'nosecone', materialId: 'cardboard', shape: 'conical',
        length: 0.4, baseDiameter: 0.08, wallThickness: 0.002, isHollow: true },
      coneFin,
    ]);
    expect(finContribution(cone).c.cna).toBe(computeTrapezoidFinAero(coneFin, 0.1, 0.04, 0.08).cna);

    // Von Karman at u=0.5: r = R/sqrt(2) -> D = 0.08/sqrt(2).
    const vkFin = fins({ axialOffset: 0.1, rootChord: 0.2 });
    const vk = vehicle([
      { id: 'nose', name: 'nose', type: 'nosecone', materialId: 'cardboard', shape: 'vonkarman',
        length: 0.4, baseDiameter: 0.08, wallThickness: 0.002, isHollow: true },
      vkFin,
    ]);
    expect(finContribution(vk).c.cna).toBe(computeTrapezoidFinAero(vkFin, 0.1, 0.08 / Math.SQRT2, 0.08).cna);
  });

  it('a root with negative offset is judged by overlap (the torrent pattern)', () => {
    const fin = fins({ axialOffset: -0.05, rootChord: 0.2 }); // 1.05..1.25, 0.15 on the fincan
    const v = vehicle([
      nose(0.2, 0.06),
      tube('bt', 0.8, 0.06),
      transition('tr', 0.1, 0.06, 0.04),
      tube('fincan_fins_should_use', 0.3, 0.08),
      fin,
    ]);
    // Reference diameter is the fincan's 0.08 m (last body tube).
    expect(finContribution(v).c.cna).toBe(computeTrapezoidFinAero(fin, 1.05, 0.08, 0.08).cna);
  });

  it('a root with no body overlap keeps the pre-fix running diameter', () => {
    const fin = fins({ axialOffset: 2.0 });
    const v = vehicle([nose(0.2, 0.06), tube('bt', 0.4, 0.06), transition('tr', 0.1, 0.06, 0.04), fin]);
    expect(finContribution(v).c.cna).toBe(computeTrapezoidFinAero(fin, 2.2, 0.04, 0.06).cna);
  });

  it('elliptical and freeform fin sets use the mounting body too', () => {
    const elliptical: EllipticalFinSetComponent = {
      id: 'fins', name: 'fins', type: 'ellipticalfinset', materialId: 'balsa',
      finCount: 3, rootChord: 0.2, span: 0.08, thickness: 0.003, axialOffset: 0.2,
    };
    const ev = vehicle([nose(0.2, 0.05), tube('bt', 0.5, 0.05), transition('tr', 0.1, 0.05, 0.035), elliptical]);
    const e = finContribution(ev);
    expect(e.c.cna).toBe(computeEllipticalFinAero(elliptical, 0.4, 0.05, 0.05).cna);

    const points = trapezoidPlanformPoints(0.1, 0.05, 0.06, 0.03);
    const freeform: FreeformFinSetComponent = {
      id: 'fins', name: 'fins', type: 'freeformfinset', materialId: 'balsa',
      finCount: 4, points, thickness: 0.003, crossSection: 'rounded', axialOffset: 0.2,
    };
    const fv = vehicle([nose(0.2, 0.05), tube('bt', 0.5, 0.05), transition('tr', 0.1, 0.05, 0.035), freeform]);
    const f = finContribution(fv);
    expect(f.c.cna).toBe(computeFreeformFinAero(freeform, 0.4, 0.05, 0.05).cna);
  });

  it('the Aero Plots curve takes its subsonic CP from the corrected stability', () => {
    const stability = computeRocketStability(PRESET_SPACEPORT_AMERICA);
    const curves = computeAerodynamicCurves(PRESET_SPACEPORT_AMERICA, false, 2);
    // M=0: no fin-slope scaling and no supersonic shift, so the plot's first
    // CP is the corrected Barrowman total, not the pre-fix 2.255 m.
    expect(curves.dragCurves[0].cp).toBe(stability.cp);
  });

  it('Round 2 affected input vehicles move by the Gate 1 predictions (no outcome access)', () => {
    // Gate 1 predictions (M0, calibers of reference diameter). The committed
    // docs/flight-validation/round2-predictions.json is NOT touched: it keeps
    // its pre-P4 model identity.
    const predicted: Record<string, number> = {
      'bella-lui': 0.0869,
      'erebus-11': 0.2919,
      'lince': 0.0688,
      'juno-iii': 0.1626,
      // Gate 1 quoted 0.8628 for valkyrie: that replica used root-tip sweep
      // (0.03) instead of the vehicle stated sweepLength 0.10. Corrected
      // prediction from the real geometry: 0.8921 (still a threshold cross).
      'valkyrie': 0.8921,
    };
    const rows: string[] = [];
    for (const v of ROUND2_VEHICLES) {
      const built = buildVehicle(v, NOMINAL, 'm');
      const { s, c } = finContribution(built);
      const finComp = built.components.find((x) => x.id === 'fins') as TrapezoidFinSetComponent;
      const finStart = c.axialStart!;
      const tail = built.components.find((x) => x.id === 'tail') as { aftDiameter: number; foreDiameter: number } | undefined;
      const legacyDiameter = tail ? tail.aftDiameter : s.referenceDiameter;
      // The pre-fix rule in one line: the last body component's diameter.
      const oldFin = computeTrapezoidFinAero(finComp, finStart, legacyDiameter, s.referenceDiameter);
      if (tail === undefined) {
        // Unaffected by construction: the mounting body is the last tube and
        // the contribution is bit-identical to the pre-fix closed form.
        expect(c.cna, `${v.id} cna must not move`).toBe(oldFin.cna);
        expect(c.cp, `${v.id} cp must not move`).toBe(oldFin.cp);
        rows.push(`${v.id}: unaffected (no transition before the fin set)`);
        continue;
      }
      const want = predicted[v.id];
      expect(want, `${v.id} has a transition and needs a prediction`).toBeDefined();
      const oldCna = s.totalCNa - c.cna! + oldFin.cna;
      const oldMoment = s.totalCNa * s.cp - c.cna! * c.cp! + oldFin.cna * oldFin.cp;
      const oldCp = oldMoment / oldCna;
      const dcpCal = (s.cp - oldCp) / s.referenceDiameter;
      expect(dcpCal, `${v.id} dCP`).toBeCloseTo(want, 3);
      const oldMargin = (oldCp - s.cg) / s.referenceDiameter;
      const newMargin = (s.cp - s.cg) / s.referenceDiameter;
      const dcpMm = dcpCal * s.referenceDiameter * 1000;
      rows.push(`${v.id}: dCP=${dcpMm.toFixed(3)} mm (${dcpCal.toFixed(4)} cal), `
        + `CP ${oldCp.toFixed(9)} -> ${s.cp.toFixed(9)} m, margin ${oldMargin.toFixed(3)} -> ${newMargin.toFixed(3)} cal`);
    }
    console.log(`P4 round2 (input geometry, dry M0; predictions are pre-P4 model identity):\n${rows.join('\n')}`);
    expect(rows).toHaveLength(10);
  });
});
